const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the study area - Isles Dernières Barrier Islands Refuge, Louisiana
  const refuge = ee.Geometry.Polygon([
    [[-90.95, 29.0], [-90.95, 29.15], [-90.65, 29.15], [-90.65, 29.0], [-90.95, 29.0]]
  ]);

  // Function to mask clouds for Landsat 5/7
  function maskL57Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  // Function to mask clouds for Landsat 8/9
  function maskL89Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  // Function to calculate MNDWI and classify land
  function addLandMask(image) {
    const green = image.select('SR_B2');
    const swir = image.select('SR_B5');
    const mndwi = green.subtract(swir).divide(green.add(swir)).rename('MNDWI');
    const land = mndwi.lt(0).rename('land');
    return image.addBands([mndwi, land]);
  }

  function addLandMaskL89(image) {
    const green = image.select('SR_B3');
    const swir = image.select('SR_B6');
    const mndwi = green.subtract(swir).divide(green.add(swir)).rename('MNDWI');
    const land = mndwi.lt(0).rename('land');
    return image.addBands([mndwi, land]);
  }

  // Get 2000 data (Landsat 7)
  let col2000 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(refuge)
    .filterDate('2000-01-01', '2000-12-31')
    .map(maskL57Clouds)
    .map(addLandMask);

  const size2000 = col2000.size().getInfo();
  console.log(`2000 Images found: ${size2000}`);

  if (size2000 === 0) {
    console.log('No images for 2000');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get 2024 data (Landsat 9)
  let col2024 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(refuge)
    .filterDate('2024-01-01', '2024-12-31')
    .map(maskL89Clouds)
    .map(addLandMaskL89);

  const size2024 = col2024.size().getInfo();
  console.log(`2024 Images found: ${size2024}`);

  if (size2024 === 0) {
    console.log('No images for 2024, trying Landsat 8');
    col2024 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(refuge)
      .filterDate('2024-01-01', '2024-12-31')
      .map(maskL89Clouds)
      .map(addLandMaskL89);

    const size2024_l8 = col2024.size().getInfo();
    console.log(`2024 Landsat 8 Images found: ${size2024_l8}`);

    if (size2024_l8 === 0) {
      console.log('No images for 2024');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Create median composites
  const img2000 = col2000.median();
  const img2024 = col2024.median();

  // Calculate land area for 2000
  const land2000Stats = img2000.select('land').reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: refuge,
    scale: 30,
    maxPixels: 1e9
  });

  const landPixels2000 = land2000Stats.get('land_sum').getInfo();
  const totalPixels2000 = land2000Stats.get('land_count').getInfo();

  console.log(`2000: Land pixels = ${landPixels2000}, Total valid pixels = ${totalPixels2000}`);

  if (totalPixels2000 === 0) {
    console.log('No valid pixels for 2000 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate land area for 2024
  const land2024Stats = img2024.select('land').reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: refuge,
    scale: 30,
    maxPixels: 1e9
  });

  const landPixels2024 = land2024Stats.get('land_sum').getInfo();
  const totalPixels2024 = land2024Stats.get('land_count').getInfo();

  console.log(`2024: Land pixels = ${landPixels2024}, Total valid pixels = ${totalPixels2024}`);

  if (totalPixels2024 === 0) {
    console.log('No valid pixels for 2024 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (landPixels2000 === null || landPixels2024 === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  // Calculate land area in km²
  const landArea2000 = (landPixels2000 * 30 * 30) / 1e6;
  const landArea2024 = (landPixels2024 * 30 * 30) / 1e6;
  const areaLost = landArea2000 - landArea2024;
  const percentLost = (areaLost / landArea2000) * 100;

  console.log(`2000 Land Area: ${landArea2000.toFixed(2)} km²`);
  console.log(`2024 Land Area: ${landArea2024.toFixed(2)} km²`);
  console.log(`Area Lost: ${areaLost.toFixed(2)} km² (${percentLost.toFixed(1)}%)`);

  if (percentLost > 50) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
